<script setup>
import { ref } from 'vue';
import { byId, employeeName, roomName } from '../store.js';
import { dateTime, time } from '../format.js';
import Avatar from './Avatar.vue'; import Icon from './Icon.vue'; import Modal from './Modal.vue';
defineProps({ items: Array, compact: Boolean }); const selected = ref(null);
</script>
<template>
  <div v-if="!items?.length" class="empty-state small"><Icon name="events" :size="32" /><h3>Событий пока нет</h3><p>Зарегистрированные входы, выходы и отказы появятся здесь.</p></div>
  <div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Помещение</th><th>Событие</th><th>{{ compact ? 'Время' : 'Дата и время' }}</th><th>Результат</th><th><span class="sr-only">Подробности</span></th></tr></thead><tbody><tr v-for="event in items" :key="event.id"><td><div class="person-cell"><Avatar :person="byId('employees', event.employeeId)" size="sm" /><div><strong>{{ employeeName(event.employeeId) }}</strong><small v-if="!compact">{{ event.employeeId ? byId('departments', byId('employees', event.employeeId)?.departmentId)?.name : 'Не удалось установить личность' }}</small></div></div></td><td>{{ roomName(event.roomId) }}</td><td><span class="direction"><Icon :name="event.direction" :size="15" />{{ event.direction === 'entry' ? 'Вход' : 'Выход' }}</span></td><td class="mono">{{ compact ? time(event.timestamp) : dateTime(event.timestamp) }}</td><td><span class="badge" :class="event.result === 'allowed' ? 'green' : 'red'"><span class="dot"></span>{{ event.result === 'allowed' ? 'Разрешён' : 'Отказ' }}</span></td><td><button class="icon-button" :aria-label="`Подробности события ${event.id}`" @click="selected = event"><Icon name="right" :size="17" /></button></td></tr></tbody></table></div>
  <Modal v-if="selected" title="Событие прохода" @close="selected = null"><div class="detail-status" :class="selected.result"><Icon :name="selected.result === 'allowed' ? 'success' : 'alert'" :size="32" /><div><h3>{{ selected.result === 'allowed' ? 'Проход разрешён' : 'В доступе отказано' }}</h3><p>{{ selected.reason }}</p></div></div><dl class="details"><dt>Сотрудник</dt><dd>{{ employeeName(selected.employeeId) }}</dd><dt>Помещение</dt><dd>{{ roomName(selected.roomId) }}</dd><dt>Дата и время</dt><dd>{{ dateTime(selected.timestamp) }} МСК</dd><dt>Направление</dt><dd>{{ selected.direction === 'entry' ? 'Вход' : 'Выход' }}</dd><dt>Способ проверки</dt><dd>{{ selected.source === 'photo' ? 'Распознавание по фотографии' : 'Ручная имитация' }}</dd><template v-if="selected.similarity != null"><dt>Сходство лиц</dt><dd>{{ selected.similarity.toFixed(3) }} — оценка сходства, не вероятность</dd></template><template v-if="selected.fromRoomId"><dt>Переход из</dt><dd>{{ roomName(selected.fromRoomId) }}</dd></template></dl></Modal>
</template>
